function createParkingBays(siteId,prefix,total,counts,accessible=[],fleet=[]){
 const statuses=[];
 for(let i=0;i<(counts.available||0);i++)statuses.push('available');
 for(let i=0;i<(counts.reserved||0);i++)statuses.push('reserved');
 for(let i=0;i<(counts.blocked||0);i++)statuses.push('blocked');
 while(statuses.length<total)statuses.push('occupied');
 const vehicles=['Tesla Model 3 · 10AA900','Skoda Enyaq · 22BB411','Audi Q4 e-tron · 44CC712','Volvo EX30 · 15DD111','BMW iX1 · 33EE207','Kia EV6 · 48DD731','VW ID.4 · 88EE102'];
 return Array.from({length:total},(_,idx)=>{
  const n=idx+1,status=statuses[idx],type=accessible.includes(n)?'accessible':fleet.includes(n)?'fleet':'standard';
  return {id:`${siteId}-BAY-${String(n).padStart(2,'0')}`,site:siteId,label:`${prefix}-${String(n).padStart(2,'0')}`,status,type,charger:null,occupiedBy:status==='occupied'?vehicles[idx%vehicles.length]:null,reservationId:status==='reserved'?`RSV-${siteId.slice(-2)}${String(n).padStart(2,'0')}`:null,note:status==='blocked'?'Temporarily blocked by operator':null};
 });
}
