function normalizeReservation(reservation={}){
 const out={...reservation};
 out.durationMin=finiteNumber(reservation.durationMin,45);
 out.fee=finiteNumber(reservation.fee,0);
 out.estimatedCost=finiteNumber(reservation.estimatedCost,0);
 out.targetSoc=finiteNumber(reservation.targetSoc,80);
 out.requestedKwh=finiteNumber(reservation.requestedKwh,0);
 out.graceMin=finiteNumber(reservation.graceMin,10);
 out.cancellationCutoffMin=finiteNumber(reservation.cancellationCutoffMin,30);
 out.timeline=Array.isArray(reservation.timeline)?reservation.timeline:[];
 out.operatorOverride=Boolean(reservation.operatorOverride);
 return out;
}


