function normalizeTransaction(tx={}){const out={...tx};out.gross=finiteNumber(tx.gross,0);out.providerFee=finiteNumber(tx.providerFee,0);out.tax=finiteNumber(tx.tax,0);out.net=finiteNumber(tx.net,out.gross-out.providerFee-out.tax);out.refundedAmount=finiteNumber(tx.refundedAmount,0);out.timeline=Array.isArray(tx.timeline)?tx.timeline:[];out.status=tx.status||'pending';out.type=tx.type||'charging';out.retryable=Boolean(tx.retryable);return out;}
function normalizeRefund(refund={}){const out={...refund};out.amount=finiteNumber(refund.amount,0);out.status=refund.status||'review';return out;}
function normalizeRoamingSettlement(item={}){const out={...item};out.sessions=finiteNumber(item.sessions,0);out.gross=finiteNumber(item.gross,0);out.operatorReceivable=finiteNumber(item.operatorReceivable,0);out.partnerFee=finiteNumber(item.partnerFee,0);out.variance=finiteNumber(item.variance,0);out.status=item.status||'pending';return out;}
function normalizeRevenueDay(item={}){const out={...item};['energy','reservations','idle','parking','other','total'].forEach(k=>out[k]=finiteNumber(item[k],0));return out;}
function normalizeRevenueSite(item={}){const out={...item};['energy','reservations','idle','parking','other','transactions','failed'].forEach(k=>out[k]=finiteNumber(item[k],0));return out;}

