 ['peakReductionPct','reserveHeadroomKw','warningPercent','criticalPercent','batteryReserveSoc'].forEach(k=>out.energy[k]=finiteNumber(out.energy[k],defaultOperatorSettings.energy[k]));
 out.safety.auditRetentionDays=finiteNumber(out.safety.auditRetentionDays,365);out.interface.refreshSeconds=finiteNumber(out.interface.refreshSeconds,30);out.device.sessionTimeoutMin=finiteNumber(out.device.sessionTimeoutMin,30);
