function mergeById(base=[],saved=[]){const map=new Map((saved||[]).map(i=>[i.id,i]));const ids=new Set((base||[]).map(i=>i.id));return (base||[]).map(i=>({...i,...(map.get(i.id)||{})})).concat((saved||[]).filter(i=>!ids.has(i.id)));}
export function loadState(){try{const raw=localStorage.getItem(KEY);if(!raw)return structuredClone(seed);const saved=JSON.parse(raw);const fresh=structuredClone(seed);return {...fresh,...saved,network:{...fresh.network,...(saved.network||{})},operatorSettings:normalizeOperatorSettings(saved.operatorSettings||fresh.operatorSettings),revenue:{...fresh.revenue,...(saved.revenue||{})},sites:mergeById(fresh.sites,saved.sites),parkingBays:mergeById(fresh.parkingBays,saved.parkingBays),chargers:mergeById(fresh.chargers,saved.chargers),connectors:mergeById(fresh.connectors,saved.connectors),sessions:mergeById(fresh.sessions,saved.sessions).map(normalizeSession),reservations:mergeById(fresh.reservations,saved.reservations).map(normalizeReservation),maintenanceAlerts:mergeById(fresh.maintenanceAlerts,saved.maintenanceAlerts).map(normalizeMaintenanceAlert),maintenanceTickets:mergeById(fresh.maintenanceTickets,saved.maintenanceTickets).map(normalizeMaintenanceTicket),technicians:mergeById(fresh.technicians,saved.technicians),supportCases:mergeById(fresh.supportCases,saved.supportCases).map(normalizeSupportCase),emergencyEvents:mergeById(fresh.emergencyEvents,saved.emergencyEvents).map(normalizeEmergencyEvent),energyProfiles:mergeById(fresh.energyProfiles,saved.energyProfiles).map(normalizeEnergyProfile),energyAlerts:mergeById(fresh.energyAlerts,saved.energyAlerts).map(normalizeEnergyAlert),tariffs:mergeById(fresh.tariffs,saved.tariffs),revenueDaily:mergeById(fresh.revenueDaily,saved.revenueDaily).map(normalizeRevenueDay),revenueBySite:mergeById(fresh.revenueBySite,saved.revenueBySite).map(normalizeRevenueSite),financialTransactions:mergeById(fresh.financialTransactions,saved.financialTransactions).map(normalizeTransaction),refunds:mergeById(fresh.refunds,saved.refunds).map(normalizeRefund),roamingSettlements:mergeById(fresh.roamingSettlements,saved.roamingSettlements).map(normalizeRoamingSettlement),commandHistory:mergeById(fresh.commandHistory,saved.commandHistory)};}catch(e){console.error('[VoltDrive Operator] state load failed',e);return structuredClone(seed);}}
export function saveState(state){localStorage.setItem(KEY,JSON.stringify(state));}
export function siteById(state,id){return state.sites.find(x=>x.id===id)}
export function chargerById(state,id){return state.chargers.find(x=>x.id===id)}
export function connectorById(state,id){return state.connectors.find(x=>x.id===id)}
